"use client";

import { useEffect, useState } from "react";
import dynamic from "next/dynamic";
import { KanbanBoard } from "@/components/KanbanBoard";
import { LoginForm } from "@/components/LoginForm";
import { ChatToggleButton } from "@/components/ChatToggleButton";
import { BoardData, fromApiBoard, initialData, type ApiBoardData } from "@/lib/kanban";
import { clearStoredUser, getStoredUser, setStoredUser } from "@/lib/auth";

const LazyChatSidebar = dynamic(
  () => import("@/components/ChatSidebar").then((module) => module.ChatSidebar),
  { ssr: false }
);

export default function Home() {
  const [user, setUser] = useState<string | null>(null);
  const [isLoaded, setIsLoaded] = useState(false);
  const [board, setBoard] = useState<BoardData>(initialData);
  const [showChat, setShowChat] = useState(false);

  useEffect(() => {
    const storedUser = getStoredUser();
    setUser(storedUser);
    setIsLoaded(true);
  }, []);

  useEffect(() => {
    if (!user) return;

    fetch("/api/board")
      .then((response) => (response.ok ? response.json() : Promise.reject(response)))
      .then((apiBoard: ApiBoardData) => setBoard(fromApiBoard(apiBoard)))
      .catch(() => setBoard(initialData));
  }, [user]);

  const handleLogin = (username: string) => {
    setStoredUser(username);
    setUser(username);
  };

  const handleLogout = () => {
    clearStoredUser();
    setUser(null);
  };

  const handleBoardUpdate = (newBoard: BoardData) => {
    setBoard(newBoard);
  };

  if (!isLoaded) {
    return (
      <div className="flex min-h-screen items-center justify-center bg-[#f7f9fc]">
        <div className="h-8 w-8 animate-spin rounded-full border-2 border-[var(--primary-blue)] border-t-transparent" />
      </div>
    );
  }

  if (!user) {
    return <LoginForm onLogin={handleLogin} />;
  }

  return (
    <>
      <KanbanBoard
        user={user}
        onLogout={handleLogout}
        externalBoard={board}
        externalSetBoard={setBoard}
      />
      <ChatToggleButton onClick={() => setShowChat(true)} />
      {showChat && (
        <LazyChatSidebar
          board={board}
          onClose={() => setShowChat(false)}
          onBoardUpdate={handleBoardUpdate}
        />
      )}
    </>
  );
}
